using System.Collections.Frozen;

namespace BdoGrindTracker.App.Character;

internal enum CharacterSpecialization
{
    Succession,
    Awakening,
    Unique,
}

internal sealed record CharacterClass(
    string Id,
    string Name,
    CharacterSpecialization Specialization)
{
    public string DisplayName => Specialization switch
    {
        CharacterSpecialization.Succession => $"{Name} · Succession",
        CharacterSpecialization.Awakening => $"{Name} · Awakening",
        _ => Name,
    };

    public override string ToString() => DisplayName;
}

