    public static IReadOnlyList<CharacterClass> Classes { get; } = Array.AsReadOnly(
        Profiles.Select(profile => profile.Class)
            // The current public Companion loot_drops metadata lists Agent
            // (class ID 31), but 0.7.4 embeds no matching skills for it. Keep
            // this manual-only instead of fabricating an automatic mapping.
            .Append(new CharacterClass("agent", "Agent", CharacterSpecialization.Unique))
            .OrderBy(characterClass => characterClass.Name, StringComparer.Ordinal)
            .ThenBy(characterClass => characterClass.Specialization)
            .ToArray());

    public static CharacterClass? FindById(string? id) =>
        Classes.FirstOrDefault(characterClass =>
            string.Equals(characterClass.Id, id, StringComparison.Ordinal));
}
